(function(root){
 function display(value,type){if(!value)return type==='month'?'选择月份':'选择日期';if(!/^\d{4}-\d{2}(?:-\d{2})?$/.test(value))return value;return type==='month'?value.slice(0,4)+'年'+Number(value.slice(5,7))+'月':value;}
 if(typeof module!=='undefined'&&module.exports){module.exports={display};return;}
 let scheduled=false;const selector='input[type=date],input[type=month]';
 function refresh(){if(!document.body)return;for(const wrap of document.querySelectorAll('.date-control')){const input=wrap.querySelector('input');if(input&&!['date','month'].includes(input.type))wrap.replaceWith(input);}for(const input of document.querySelectorAll(selector)){let wrap=input.parentElement;if(!wrap.classList.contains('date-control')){wrap=document.createElement('span');wrap.className='date-control';wrap.dataset.dateField=input.id||'';input.before(wrap);wrap.append(input);const value=document.createElement('span');value.className='date-control-value';value.setAttribute('aria-hidden','true');const icon=document.createElement('span');icon.className='date-control-icon';icon.setAttribute('aria-hidden','true');icon.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16"/></svg>';wrap.append(value,icon);}const value=wrap.querySelector('.date-control-value'),text=display(input.value,input.type);if(value.textContent!==text)value.textContent=text;wrap.classList.toggle('is-empty',!input.value);wrap.classList.toggle('is-disabled',input.disabled);if(wrap.hidden!==input.hidden)wrap.hidden=input.hidden;}}
 function schedule(){if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;refresh();});}
 new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['type','disabled','hidden']});for(const e of ['input','change','click','family-ledger-ready','family-app-ready'])document.addEventListener(e,schedule,true);window.addEventListener('hashchange',schedule);window.addEventListener('pageshow',schedule);root.FamilyDateControls={refresh};refresh();
})(globalThis);
